(() => {
const B = game.level.boss, P = game.player;
const log = [];
let t = 0, deaths0 = game.stats.deaths;
const mode = window.__mode;
while (t < 150 && B.state !== 'dead' && B.state !== 'dying') {
  if (game.state === 'dead') {
    document.getElementById('screen-dead').classList.add('hidden');
    game.level.respawn(); game.player.roll = 0; game.player.landDip = 0; game.setState('play');
    log.push('X');
  }
  let inp = { fire: true };
  if (mode === 'dodge') {
    inp = { fire: true, moveX: Math.floor(t / 2.5) % 2 ? 1 : -1, jumpEvery: 1.3 };
  }
  game.debug.simulate(1, inp, true);
  t += 1;
  if (t % 5 === 0) log.push(B.hp + '/' + P.health);
}
return { diff: game.diffKey, mode, maxHp: B.maxHp, secs: t, bossHp: B.hp, bstate: B.state, phase: B.phase, deaths: game.stats.deaths - deaths0, log: log.join(' '), tally: game.combat.tally };
})()

